SET
   space_label = REGEXP_REPLACE(
       REPLACE(
           public.unaccent(TRIM(space_label)),
           '''',
           ''
       ),
       '[^a-zA-Z0-9\s]',
       '',
       'g'
   ),
   ccaa_label = REGEXP_REPLACE(
       REPLACE(
           public.unaccent(TRIM(ccaa_label)),
           '''',
           ''
       ),
       '[^a-zA-Z0-9\s]',
       '',
       'g'
   ),
   province_label = REGEXP_REPLACE(
       REPLACE(
           public.unaccent(TRIM(province_label)),
           '''',
           ''
       ),
       '[^a-zA-Z0-9\s]',
       '',
       'g'
   );

